def _selection_runtime(runtime: MutableMapping[str, Any]) -> Dict[str, Any]:
    env = dict(runtime)
    env.update(
        {
            "Any": Any,
            "Dict": Dict,
            "List": List,
            "Mapping": Mapping,
            "MutableMapping": MutableMapping,
            "Optional": Optional,
            "Path": Path,
            "Sequence": Sequence,
            "Tuple": Tuple,
            "copy": copy,
            "date": date,
            "hashlib": hashlib,
            "html": html,
            "json": json,
            "pd": pd,
            "re": re,
            "time": time,
        }
    )
    return env


def _exec_selection_code(code: str, env: Dict[str, Any]) -> None:
    wrapper_name = "__quarter_notes_selection_exec__"
    indented = "\n".join(f"    {line}" if line else "" for line in code.splitlines())
    wrapped = f"def {wrapper_name}():\n{indented}\n    return locals()\n"
    exec(wrapped, env, env)
    local_env = env.pop(wrapper_name)()
    env.update(local_env)


def select_quarter_notes_ui_visible_rows(
    deps: QuarterNotesUiSelectionDeps,
) -> QuarterNotesUiSelectionResult:
    env = _selection_runtime(deps.runtime)
    _exec_selection_code(f"{_SELECTION_PRELUDE_CODE}\n{_SELECTION_FINALIZATION_CODE}", env)
    rows_by_quarter = {
        key: [dict(item) for item in list(value or [])]
        for key, value in dict(env.get("rows_by_quarter") or {}).items()
    }
    ui_info_rows = list(env.get("ui_info_rows") or [])
    helpers = {name: env[name] for name in _SELECTION_EXPORT_NAMES if name in env}
    selection_counts = {
        "quarters": len(list(env.get("quarters") or [])),
        "rows": sum(len(list(rows or [])) for rows in rows_by_quarter.values()),
        "ui_info_rows": len(ui_info_rows),
        "helpers": len(helpers),
    }
    return QuarterNotesUiSelectionResult(
        rows_by_quarter=rows_by_quarter,
        ui_info_rows=ui_info_rows,
        selection_counts=selection_counts,
        helpers=helpers,
    )
